1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const neighborsOf = ([x, y]: Cell): Cell[] =>
7	  [-1, 0, 1].flatMap((dx) =>
8	    [-1, 0, 1]
9	      .filter((dy) => !(dx === 0 && dy === 0))
10	      .map((dy): Cell => [x + dx, y + dy]),
11	  );
12	
13	const isLive = (cell: Cell, liveCells: Cell[]): boolean =>
14	  liveCells.some((liveCell) => isSameCell(cell, liveCell));
15	
16	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
17	  neighborsOf(cell).filter((neighbor) => isLive(neighbor, liveCells)).length;
18	
19	const withoutDuplicates = (cells: Cell[]): Cell[] =>
20	  cells.filter(
21	    (cell, index) =>
22	      index === cells.findIndex((other) => isSameCell(cell, other)),
23	  );
24	
25	const isLiveNextGeneration = (cell: Cell, liveCells: Cell[]): boolean => {
26	  const liveNeighbors = countLiveNeighbors(cell, liveCells);
27	  return liveNeighbors === 3 || (liveNeighbors === 2 && isLive(cell, liveCells));
28	};
29	
30	const cellsThatCouldChange = (liveCells: Cell[]): Cell[] =>
31	  withoutDuplicates(liveCells.flatMap((cell) => [cell, ...neighborsOf(cell)]));
32	
33	export const nextGeneration = (liveCells: Cell[]): Cell[] =>
34	  cellsThatCouldChange(liveCells).filter((cell) =>
35	    isLiveNextGeneration(cell, liveCells),
36	  );
